/* Carnet IFSI — cours complets d'anatomie et physiologie (4/4) : système endocrinien, appareil locomoteur, reproduction, grossesse et naissance. */
(()=>{const L=[
CV("endocrino-c","anat","Le système endocrinien","60 min","2.2 2.7|B.1","gland",
 ["Définir une **hormone** et le principe du **rétrocontrôle**","Décrire l'**axe hypothalamo-hypophysaire** et ses hormones","Connaître le rôle de la **thyroïde** et des **parathyroïdes**","Expliquer le rôle des **surrénales** : cortisol, aldostérone, adrénaline","Comprendre la **régulation de la glycémie** par le pancréas","Relier la physiologie au diabète, aux dysthyroïdies et à la corticothérapie"],
 [
 {h:"Hormones et glandes endocrines",chip:"Hormones",b:[
  {t:"p",ps:["Une **glande endocrine** fabrique des **hormones** et les libère directement **dans le sang**. Elle s'oppose à une glande **exocrine**, qui déverse sa sécrétion dans un conduit vers l'extérieur ou dans le tube digestif (glandes salivaires, sudoripares, pancréas exocrine).","Une hormone est un **messager chimique** : transportée par le sang dans tout le corps, elle n'agit que sur les **cellules cibles** qui possèdent son **récepteur**. Une même hormone peut agir sur plusieurs organes : l'insuline agit sur le foie, les muscles et le tissu adipeux.","On distingue les hormones **peptidiques** (insuline, glucagon, ADH, hormones hypophysaires), qui agissent sur un récepteur de la membrane et sont détruites dans le tube digestif — d'où l'insuline **injectable** ; les hormones **stéroïdes** (cortisol, aldostérone, œstrogènes, testostérone), dérivées du cholestérol, qui entrent dans la cellule — d'où les corticoïdes actifs par la bouche ; et les hormones dérivées d'acides aminés (**hormones thyroïdiennes**, **adrénaline**)."]},
  {t:"map",m:"glandes",cap:"Les principales glandes endocrines : hypophyse, thyroïde, parathyroïdes, surrénales, pancréas, gonades"},
  {t:"table",rows:[["Hypothalamus","hormones de commande de l'hypophyse ; fabrique l'**ADH** et l'**ocytocine**"],["Hypophyse","TSH, ACTH, FSH, LH, GH, prolactine ; libère ADH et ocytocine"],["Thyroïde","**T3, T4** (métabolisme) ; calcitonine"],["Parathyroïdes","**PTH** (augmente la calcémie)"],["Surrénales","**cortisol**, **aldostérone**, adrénaline, noradrénaline"],["Pancréas (îlots de Langerhans)","**insuline**, **glucagon**"],["Ovaires","œstrogènes, progestérone"],["Testicules","testostérone"],["Épiphyse","mélatonine (rythme veille-sommeil)"]],note:"D'autres organes sécrètent des hormones : rein (EPO, rénine, vitamine D active), cœur (peptide natriurétique), estomac, tissu adipeux, placenta (hCG)."},
  {t:"analogie",txt:"Le système nerveux est le **téléphone** du corps : un message rapide, précis, vers un seul destinataire. Le système endocrinien est le **courrier** : la lettre (hormone) part dans le sang vers toutes les adresses, mais seules les maisons qui ont la bonne boîte aux lettres (récepteur) la reçoivent. C'est plus lent, mais l'effet dure plus longtemps."}]},
 {h:"Le rétrocontrôle",chip:"Rétrocontrôle",b:[
  {t:"p",ps:["La sécrétion d'une hormone est réglée en permanence pour maintenir un équilibre. Le mécanisme principal est le **rétrocontrôle négatif** (ou « feedback » négatif) : quand l'hormone est en quantité suffisante dans le sang, elle **freine sa propre production** en agissant sur la glande qui la commande.","Exemple : la thyroïde produit T3 et T4 sous l'effet de la **TSH** hypophysaire. Si T3/T4 augmentent, l'hypophyse diminue la TSH ; si elles baissent, la TSH augmente. C'est pourquoi on dose la **TSH** pour surveiller la thyroïde : elle est **haute** dans l'hypothyroïdie et **effondrée** dans l'hyperthyroïdie."]},
  {t:"etapes",items:["**Commande** : l'hypothalamus stimule l'hypophyse","**Relais** : l'hypophyse sécrète une stimuline (TSH, ACTH…)","**Production** : la glande cible fabrique son hormone","**Effet** sur les organes","**Freinage** : l'hormone en excès freine l'hypothalamus et l'hypophyse"]},
  {t:"info",txt:"Le **rétrocontrôle positif** est rare : l'hormone stimule encore plus sa propre sécrétion jusqu'à un événement final. Exemples : l'**ocytocine** pendant l'accouchement (les contractions entraînent plus d'ocytocine, donc plus de contractions) et le **pic de LH** qui déclenche l'ovulation."},
  {t:"exemple",h:"La corticothérapie prolongée",ps:["Un patient prend de la prednisone depuis plusieurs mois. Ce cortisol « extérieur » freine par rétrocontrôle l'hypothalamus et l'hypophyse : l'ACTH baisse et les **surrénales se mettent au repos**.","Si le traitement est **arrêté brutalement**, les surrénales ne relancent pas tout de suite leur production : risque d'**insuffisance surrénale aiguë** (fatigue intense, hypotension, douleurs abdominales, malaise). D'où la **décroissance progressive** des doses."]}]},
 {h:"L'axe hypothalamo-hypophysaire",chip:"Hypophyse",b:[
  {t:"p",ps:["L'**hypothalamus**, à la base du cerveau, fait le lien entre le système nerveux et le système hormonal. Il commande l'**hypophyse**, petite glande de la taille d'un pois logée dans une cavité osseuse à la base du crâne (la selle turcique), reliée à lui par une tige.","L'hypophyse comprend deux parties. L'**antéhypophyse** fabrique des hormones qui commandent d'autres glandes : la **TSH** (thyroïde), l'**ACTH** (surrénales), la **FSH** et la **LH** (ovaires et testicules), l'**hormone de croissance (GH)** et la **prolactine** (lactation). La **posthypophyse** stocke et libère deux hormones fabriquées par l'hypothalamus : l'**ADH** (hormone antidiurétique, qui fait retenir l'eau par le rein) et l'**ocytocine** (contractions de l'utérus, éjection du lait)."]},
  {t:"schema",k:"hypophyse",cap:"L'hypothalamus commande l'hypophyse, qui commande à son tour la thyroïde, les surrénales et les gonades ; les hormones produites freinent en retour l'axe."},
  {t:"table",rows:[["TSH","stimule la thyroïde"],["ACTH","stimule le cortex surrénalien (cortisol)"],["FSH, LH","ovaires (cycle, ovulation) et testicules (spermatozoïdes, testostérone)"],["GH","croissance des os et des muscles ; mobilise les graisses"],["Prolactine","production du lait après l'accouchement"],["ADH","réabsorption d'eau par le rein : urines concentrées"],["Ocytocine","contractions utérines, éjection du lait, attachement"]]},
  {t:"cols",cols:[{h:"Trop peu d'ADH : diabète insipide",tone:"blue",items:["Urines très abondantes et **diluées** (parfois plus de 5 L par jour)","Soif intense","Risque de déshydratation et d'hypernatrémie","Après traumatisme crânien, chirurgie de l'hypophyse"]},{h:"Trop d'ADH : SIADH",tone:"coral",items:["Le rein retient trop d'eau","**Hyponatrémie** de dilution : confusion, nausées, convulsions","Causes : certains cancers du poumon, médicaments (antidépresseurs), pathologies cérébrales","Traitement : restriction hydrique"]}]}]},
 {h:"La thyroïde",chip:"Thyroïde",b:[
  {t:"p",ps:["La **thyroïde** est une glande en forme de papillon située à la **face antérieure du cou**, sous le larynx, devant la trachée. Elle capte l'**iode** apporté par l'alimentation (sel iodé, poissons, laitages) pour fabriquer les hormones **T4** (thyroxine) et **T3**, la forme active.","Les hormones thyroïdiennes règlent la **vitesse de fonctionnement** de presque toutes les cellules : production de chaleur et consommation d'énergie, fréquence cardiaque, transit, humeur et vigilance, renouvellement de la peau et des cheveux. Chez le fœtus et le nourrisson, elles sont indispensables au **développement du cerveau** et à la croissance : l'hypothyroïdie congénitale est dépistée chez tous les nouveau-nés à J3.","La thyroïde produit aussi la **calcitonine**, qui fait légèrement baisser la calcémie."]},
  {t:"cols",cols:[{h:"Hypothyroïdie (tout ralentit)",tone:"blue",items:["Fatigue, lenteur, somnolence","**Frilosité**","Prise de poids modérée, constipation","Bradycardie","Peau sèche, cheveux cassants, œdème du visage","Humeur dépressive, troubles de mémoire","TSH **élevée**, T4 basse"]},{h:"Hyperthyroïdie (tout accélère)",tone:"coral",items:["Nervosité, insomnie, tremblements","**Thermophobie**, sueurs","Amaigrissement malgré l'appétit, diarrhée","**Tachycardie**, palpitations, risque de fibrillation","Parfois yeux saillants (maladie de Basedow)","TSH **effondrée**, T4 élevée"]}]},
  {t:"valeurs",rows:[["TSH","premier examen pour explorer la thyroïde","0,4–4 mUI/L","green"],["T4 libre","hormone produite par la thyroïde","≈ 10–22 pmol/L","green"]],note:"Les normes varient selon les laboratoires ; toujours se référer aux valeurs indiquées sur le compte rendu."},
  {t:"exemple",h:"La lévothyroxine (Levothyrox®)",ps:["Elle remplace l'hormone manquante dans l'hypothyroïdie. Elle se prend **le matin à jeun**, 20 à 30 minutes avant le petit-déjeuner, à distance du calcium, du fer et des pansements gastriques qui diminuent son absorption.","Le dosage est ajusté sur la TSH, contrôlée 6 à 8 semaines après chaque changement de dose. Un surdosage donne des signes d'hyperthyroïdie : palpitations, insomnie, amaigrissement."]},
  {t:"expliquer",qui:"à une patiente",txt:"« Votre thyroïde fonctionne comme l'accélérateur de votre corps. Quand elle ne produit pas assez, tout ralentit : vous êtes fatiguée, frileuse, constipée. Le comprimé remplace simplement ce qui manque ; il faut le prendre tous les matins à jeun, à vie, et contrôler la prise de sang régulièrement. »"}]},
 {h:"Les parathyroïdes et le calcium",chip:"Calcium",b:[
  {t:"p",ps:["Les **parathyroïdes** sont quatre petites glandes de quelques millimètres, situées **derrière la thyroïde**. Elles sécrètent la **PTH** (parathormone) dès que la calcémie baisse.","La PTH fait **monter la calcémie** de trois façons : elle libère du calcium de l'**os** (activation des ostéoclastes), elle diminue sa perte dans les urines (**rein**) et elle active la **vitamine D**, qui augmente l'absorption du calcium par l'**intestin**.","La **vitamine D** est fabriquée par la peau sous l'effet du soleil (ou apportée par l'alimentation et les compléments), transformée par le foie puis activée par le rein. Elle est indispensable à la minéralisation de l'os : sa carence donne le **rachitisme** chez l'enfant et favorise l'**ostéoporose** et les chutes chez la personne âgée."]},
  {t:"valeurs",rows:[["Calcémie totale","à interpréter avec l'albumine","2,20–2,60 mmol/L","green"],["Hypocalcémie","fourmillements, crampes, tétanie, troubles du rythme","< 2,20 mmol/L","coral"],["Hypercalcémie","fatigue, soif, constipation, confusion","> 2,60 mmol/L","amber"]]},
  {t:"exemple",h:"Après une thyroïdectomie",ps:["Lors de l'ablation de la thyroïde, les parathyroïdes peuvent être lésées : **hypocalcémie** dans les jours qui suivent. Signes à rechercher : **fourmillements autour de la bouche et des doigts**, crampes, contractures des mains. La calcémie est contrôlée après l'intervention.","On surveille aussi la **voix** (le nerf récurrent, qui commande les cordes vocales, passe derrière la thyroïde : dysphonie) et le **cou** (un hématome compressif peut gêner la respiration : urgence)."]}]},
 {h:"Les glandes surrénales",chip:"Surrénales",b:[
  {t:"p",ps:["Les deux **glandes surrénales** coiffent le pôle supérieur de chaque rein. Elles comportent deux parties aux rôles différents.","La **corticosurrénale** (partie externe) fabrique des hormones stéroïdes : le **cortisol**, hormone de l'adaptation au stress, qui augmente la glycémie, freine l'inflammation et l'immunité, et suit un **rythme circadien** (pic vers 8 h du matin, minimum vers minuit) ; l'**aldostérone**, qui fait retenir le **sodium** et l'eau par le rein et éliminer le **potassium** (système rénine-angiotensine-aldostérone) ; et des androgènes en petite quantité.","La **médullosurrénale** (partie centrale) libère l'**adrénaline** et la **noradrénaline** lors d'un stress aigu : c'est la réaction de **lutte ou fuite** — accélération du cœur, hausse de la tension, dilatation des bronches et des pupilles, mobilisation du glucose, sueurs."]},
  {t:"duo",items:[{tag:"Cortisol",tone:"amber",txt:"Stress **prolongé** : glycémie ↑, inflammation ↓",sub:"stéroïde, rythme circadien, pic le matin"},{tag:"Adrénaline",tone:"coral",txt:"Stress **immédiat** : cœur, tension, bronches ↑",sub:"en quelques secondes, effet bref"}]},
  {t:"table",rows:[["Hyperglycémie, diabète cortico-induit","surveiller la glycémie capillaire"],["Rétention d'eau et de sel, HTA","régime peu salé, poids, tension"],["Hypokaliémie","kaliémie, parfois supplémentation"],["Ostéoporose, fonte musculaire","calcium, vitamine D, activité physique"],["Infections favorisées, cicatrisation retardée","signes infectieux parfois masqués"],["Troubles du sommeil et de l'humeur, excitation","prise le matin, observer le comportement"],["Visage arrondi, prise de poids","effets du traitement prolongé"],["Ulcère gastrique (surtout avec les AINS)","douleurs épigastriques, selles noires"]],note:"Effets indésirables d'une corticothérapie prolongée et surveillance infirmière correspondante."},
  {t:"pieges",items:["Arrêter brutalement une corticothérapie de plus de quelques semaines : risque d'insuffisance surrénale aiguë","Donner les corticoïdes le soir : ils perturbent le sommeil et le rythme naturel du cortisol (prise le **matin**)","Oublier que la fièvre et les signes d'infection peuvent être atténués sous corticoïdes"]}]},
 {h:"Le pancréas endocrine et la glycémie",chip:"Glycémie",b:[
  {t:"p",ps:["Le pancréas est une glande mixte : sa partie **exocrine** produit le suc pancréatique pour la digestion, sa partie **endocrine** est formée d'amas de cellules dispersés, les **îlots de Langerhans** (1 à 2 % de la glande). Les cellules **bêta** sécrètent l'**insuline**, les cellules **alpha** le **glucagon**.","Le glucose est le carburant principal des cellules, et le seul du cerveau en temps normal. La glycémie est maintenue entre environ **0,70 et 1,10 g/L à jeun**.","Après un repas, la glycémie monte : l'**insuline** fait entrer le glucose dans les muscles et le tissu adipeux et le fait stocker dans le foie sous forme de **glycogène**. C'est la **seule hormone hypoglycémiante**. À jeun ou lors d'un effort, le **glucagon** libère le glucose stocké par le foie. Plusieurs hormones sont **hyperglycémiantes** : glucagon, **cortisol**, **adrénaline**, hormone de croissance — d'où l'hyperglycémie lors d'un stress, d'une infection ou d'une corticothérapie."]},
  {t:"duo",items:[{tag:"Insuline",tone:"blue",txt:"Fait **baisser** la glycémie",sub:"après les repas · stockage · cellules bêta"},{tag:"Glucagon",tone:"amber",txt:"Fait **monter** la glycémie",sub:"à jeun, à l'effort · déstockage · cellules alpha"}]},
  {t:"valeurs",rows:[["Glycémie à jeun normale","après 8 h sans manger","0,70–1,10 g/L","green"],["Hypoglycémie (diabétique)","resucrage immédiat","< 0,70 g/L","coral"],["Diabète","à jeun, contrôlé deux fois","≥ 1,26 g/L","amber"],["HbA1c","reflet des 3 derniers mois","< 7 % le plus souvent visé","blue"]]},
  {t:"cols",cols:[{h:"Diabète de type 1",tone:"blue",items:["Destruction auto-immune des cellules bêta","Plus d'insuline : traitement **par insuline** obligatoire","Début souvent jeune et brutal","Risque d'acidocétose"]},{h:"Diabète de type 2",tone:"amber",items:["**Insulinorésistance** puis épuisement du pancréas","Lié au surpoids, à la sédentarité, à l'hérédité","Hygiène de vie, antidiabétiques oraux, puis insuline si besoin","Longtemps silencieux : complications à la découverte"]}]},
  {t:"schema",k:"insuline",cap:"Les insulines utilisées dans le diabète reproduisent la sécrétion normale : une insuline lente de fond et des insulines rapides au moment des repas."},
  {t:"calc",h:"Convertir une glycémie",q:"Le lecteur affiche 7,2 mmol/L. Quelle est la glycémie en g/L ?",steps:["Pour passer des g/L aux mmol/L, on multiplie par **5,5** (masse molaire du glucose ≈ 180 g/mol)","Dans l'autre sens, on divise par 5,5 : 7,2 ÷ 5,5 ≈ 1,31"],r:"7,2 mmol/L ≈ **1,31 g/L** : glycémie élevée si elle est mesurée à jeun."},
  {t:"exemple",h:"Hypoglycémie : reconnaître et agir",ps:["Signes : **sueurs**, tremblements, pâleur, faim, palpitations (réaction adrénergique), puis troubles du comportement, confusion, malaise, convulsions, coma (le cerveau manque de glucose).","Patient conscient : **15 g de sucre rapide** (3 morceaux de sucre, un verre de jus de fruits), contrôle à 15 minutes, puis collation. Patient inconscient : position latérale de sécurité, **rien par la bouche**, glucagon ou glucosé IV sur prescription, appel du médecin."]}]},
 {h:"Les gonades et les autres hormones",chip:"Gonades",b:[
  {t:"p",ps:["Les **gonades** sont les glandes sexuelles. Les **ovaires** produisent les **œstrogènes** (caractères sexuels féminins, prolifération de l'endomètre, protection osseuse et cardiovasculaire) et la **progestérone** (préparation et maintien de la grossesse). Les **testicules** produisent la **testostérone** (caractères sexuels masculins, masse musculaire, production des spermatozoïdes). Leur fonctionnement est commandé par la **FSH** et la **LH** hypophysaires, et démarre à la **puberté**.","L'**épiphyse** sécrète la **mélatonine** la nuit, dans l'obscurité : elle synchronise l'horloge biologique. La lumière des écrans le soir retarde sa sécrétion."]},
  {t:"verif",items:[["Pourquoi l'insuline ne se donne-t-elle pas par la bouche ?","C'est une hormone **peptidique** : elle serait détruite par les enzymes digestives. Les corticoïdes, hormones stéroïdes, sont au contraire actifs par voie orale."],["Une TSH élevée évoque quelle situation ?","Une **hypothyroïdie** : la thyroïde produit trop peu d'hormones, l'hypophyse augmente la TSH pour la stimuler (rétrocontrôle)."],["Quelles hormones font monter la glycémie ?","Le glucagon, le cortisol, l'adrénaline et l'hormone de croissance. Seule l'insuline la fait baisser."],["Que surveiller après une thyroïdectomie ?","Calcémie et signes d'hypocalcémie (fourmillements), voix (nerf récurrent), cou et respiration (hématome)."],["Pourquoi ne pas arrêter brutalement des corticoïdes au long cours ?","Les surrénales freinées par le traitement ne produisent plus assez de cortisol : risque d'insuffisance surrénale aiguë."]]},
  {t:"retenir",txt:"Une hormone est un message transporté par le sang vers des cellules qui ont son récepteur. Le **rétrocontrôle** maintient l'équilibre ; le dosage de la **TSH** explore la thyroïde, la **glycémie** le pancréas, et toute corticothérapie prolongée se diminue progressivement."}]}
 ],
 ["Glande endocrine = hormone dans le sang ; action sur les cellules ayant le récepteur","Rétrocontrôle négatif : l'hormone freine sa propre commande","Hypophyse : TSH, ACTH, FSH, LH, GH, prolactine ; ADH et ocytocine","Thyroïde : T3/T4 ; TSH haute = hypothyroïdie, basse = hyperthyroïdie","PTH et vitamine D font monter la calcémie (2,20–2,60 mmol/L)","Cortisol (stress, pic le matin), aldostérone (Na⁺ retenu, K⁺ éliminé), adrénaline (urgence)","Insuline : seule hormone hypoglycémiante ; glycémie à jeun 0,70–1,10 g/L","Hypoglycémie : 15 g de sucre, contrôle à 15 min"]),

CV("locomoteur-c","anat","L'appareil locomoteur","60 min","2.2 2.4|B.1","bone",
 ["Décrire le **squelette** et nommer les principaux os","Expliquer la **structure de l'os**, son remodelage et la **consolidation** d'une fracture","Classer les **articulations** et décrire une articulation synoviale","Comprendre la **contraction musculaire**","Décrire la **colonne vertébrale** et ses repères cliniques","Utiliser le **vocabulaire des mouvements** et prévenir les effets de l'**immobilité**"],
 [
 {h:"Le squelette",chip:"Squelette",b:[
  {t:"p",ps:["Le squelette adulte compte **206 os**. Il a cinq fonctions : **soutenir** le corps, **protéger** les organes (crâne pour le cerveau, cage thoracique pour le cœur et les poumons, rachis pour la moelle), permettre le **mouvement** grâce aux muscles, servir de **réserve de calcium** et de phosphore, et produire les **cellules du sang** dans la moelle osseuse rouge (hématopoïèse).","On distingue le **squelette axial** (crâne, colonne vertébrale, côtes et sternum) et le **squelette appendiculaire** (membres et ceintures qui les rattachent au tronc : ceinture scapulaire en haut, ceinture pelvienne en bas)."]},
  {t:"map",m:"squelette",cap:"Le squelette : rachis, épaule, poignet et main, bassin, hanche, genou, pied"},
  {t:"table",rows:[["Tête","crâne (boîte protégeant le cerveau) et face, dont la mandibule, seul os mobile"],["Thorax","**sternum**, **12 paires de côtes**, vertèbres thoraciques"],["Ceinture scapulaire","**clavicule** et **scapula** (omoplate)"],["Bras et avant-bras","**humérus** ; **radius** (côté pouce) et **ulna** (cubitus)"],["Main","8 os du carpe, 5 métacarpiens, 14 phalanges"],["Bassin","deux **os coxaux**, sacrum et coccyx"],["Cuisse et jambe","**fémur** (os le plus long), **patella** (rotule), **tibia** et **fibula** (péroné)"],["Pied","7 os du tarse (dont le talus et le calcanéus), 5 métatarsiens, 14 phalanges"]]},
  {t:"info",txt:"Les termes anatomiques actuels remplacent les anciens : **ulna** pour cubitus, **fibula** pour péroné, **scapula** pour omoplate, **patella** pour rotule. Les deux sont encore employés dans les services."}]},
 {h:"L'os : structure et renouvellement",chip:"Os",b:[
  {t:"p",ps:["Selon leur forme, les os sont **longs** (fémur, humérus), **courts** (os du carpe et du tarse, vertèbres) ou **plats** (crâne, sternum, côtes, os coxal).","Un **os long** comprend un corps, la **diaphyse**, faite d'**os compact** très dur entourant la **cavité médullaire** (moelle jaune graisseuse chez l'adulte), et deux extrémités renflées, les **épiphyses**, faites d'**os spongieux** contenant la **moelle rouge** et recouvertes de **cartilage articulaire**. Chez l'enfant, entre les deux se trouve le **cartilage de croissance**, qui permet l'allongement de l'os jusqu'à la fin de la puberté. L'os est entouré d'une membrane très innervée et vascularisée, le **périoste**, qui explique la douleur d'une fracture et permet sa réparation.","L'os est un **tissu vivant** qui se renouvelle sans cesse : les **ostéoclastes** détruisent l'os ancien, les **ostéoblastes** fabriquent l'os nouveau. Le squelette est ainsi entièrement renouvelé en une dizaine d'années. Cet équilibre dépend du **calcium**, de la **vitamine D**, des hormones (œstrogènes, PTH) et des **contraintes mécaniques** : marcher et porter son poids stimulent l'os, l'immobilité le fait fondre."]},
  {t:"schema",k:"os",cap:"Coupe d'un os long : diaphyse en os compact, épiphyses en os spongieux contenant la moelle rouge, cartilage articulaire et périoste."},
  {t:"analogie",txt:"L'os est un **chantier permanent** : une équipe démolit les vieux murs (ostéoclastes), une autre reconstruit (ostéoblastes). Tant que les deux équipes travaillent au même rythme, le bâtiment reste solide. Après la ménopause ou lors d'un alitement, l'équipe de démolition prend de l'avance : c'est l'**ostéoporose**."},
  {t:"exemple",h:"Relier à la clinique",ps:["Une fracture chez un enfant qui touche le **cartilage de croissance** peut perturber la croissance du membre : surveillance orthopédique prolongée.","La moelle rouge du **sternum** et de la **crête iliaque** (os coxal) est accessible pour un **myélogramme** ou une biopsie ostéomédullaire."]}]},
 {h:"La consolidation d'une fracture",chip:"Fracture",b:[
  {t:"p",ps:["Une fracture est une rupture de la continuité de l'os. Elle peut être **fermée** ou **ouverte** (plaie communiquant avec le foyer : risque infectieux majeur), **déplacée** ou non. L'os se répare spontanément si les fragments sont remis en place (**réduction**) et maintenus immobiles (**contention** : plâtre, attelle, ou **ostéosynthèse** chirurgicale par plaque, vis, clou)."]},
  {t:"etapes",items:["**Hématome** (premiers jours) : le sang s'accumule autour du foyer, inflammation","**Cal mou** (2 à 3 semaines) : un tissu fibreux et cartilagineux relie les fragments","**Cal osseux** (6 à 12 semaines) : le cal se minéralise, l'os redevient solide","**Remodelage** (plusieurs mois) : l'os retrouve sa forme et sa solidité"]},
  {t:"table",rows:[["Ralentissent la consolidation","âge avancé, **tabac**, dénutrition, diabète, corticoïdes, mobilité du foyer, infection, mauvaise vascularisation"],["Accélèrent","jeune âge (un enfant consolide deux fois plus vite), bonne alimentation, immobilisation correcte, reprise progressive de l'appui sur avis médical"]]},
  {t:"schema",k:"platre",cap:"Sous un plâtre, on surveille les extrémités : couleur, chaleur, sensibilité, mobilité et œdème."},
  {t:"exemple",h:"Le syndrome des loges : une urgence",ps:["Les muscles sont enfermés dans des loges inextensibles. Après une fracture ou sous un plâtre trop serré, l'œdème peut faire monter la pression et écraser vaisseaux et nerfs.","Signes d'alerte : **douleur intense, croissante, non calmée par les antalgiques** et aggravée par l'étirement des doigts, fourmillements puis perte de sensibilité, pâleur, extrémités froides. Le pouls peut rester présent ! Prévenir immédiatement le médecin : ouverture du plâtre, voire chirurgie."]}]},
 {h:"Les articulations",chip:"Articulations",b:[
  {t:"p",ps:["Une articulation est la jonction entre deux os. On distingue les articulations **fibreuses**, immobiles (sutures du crâne), **cartilagineuses**, peu mobiles (disques intervertébraux, symphyse pubienne), et **synoviales**, mobiles, les plus nombreuses (épaule, coude, hanche, genou…).","Dans une articulation **synoviale**, les extrémités osseuses sont recouvertes de **cartilage** lisse qui amortit et permet le glissement. L'articulation est entourée d'une **capsule** tapissée par la **membrane synoviale**, qui sécrète le **liquide synovial**, lubrifiant et nourricier du cartilage (le cartilage n'a pas de vaisseaux). Des **ligaments** solidifient l'ensemble ; au genou, des **ménisques** améliorent l'emboîtement."]},
  {t:"schema",k:"articulation",cap:"Une articulation synoviale : cartilage, liquide synovial, capsule et ligaments."},
  {t:"table",rows:[["Sphéroïde (énarthrose)","mouvements dans tous les plans","épaule, hanche"],["Charnière (trochlée)","flexion et extension","coude, doigts"],["Pivot","rotation","entre radius et ulna"],["En selle","opposition","base du pouce"],["Condylienne","flexion-extension, inclinaison","poignet, genou (avec un peu de rotation)"]].map(r=>[r[0],r[1]+" — "+r[2]])},
  {t:"duo",items:[{tag:"Arthrose",tone:"amber",txt:"**Usure** du cartilage",sub:"douleur mécanique à l'effort, calmée par le repos"},{tag:"Arthrite",tone:"coral",txt:"**Inflammation** de l'articulation",sub:"douleur nocturne, raideur matinale, gonflement, chaleur"}]},
  {t:"pieges",items:["Confondre entorse (atteinte d'un **ligament**) et luxation (les surfaces articulaires ne sont plus en contact)","Croire que le cartilage abîmé se répare : il ne repousse pratiquement pas, d'où l'importance de la prévention (poids, activité adaptée)"]}]},
 {h:"Les muscles et la contraction",chip:"Muscles",b:[
  {t:"p",ps:["Il existe trois types de muscles. Le muscle **squelettique** (strié), volontaire, fixé aux os par les **tendons** : il représente environ 40 % du poids du corps et compte plus de 600 muscles. Le muscle **cardiaque** (myocarde), strié mais involontaire et automatique. Le muscle **lisse**, involontaire, dans la paroi des organes creux : tube digestif, vessie, bronches, vaisseaux, utérus.","La contraction d'un muscle squelettique débute par un ordre nerveux : le **motoneurone** libère de l'**acétylcholine** au niveau de la **plaque motrice** ; le message électrique se propage dans la fibre et libère du **calcium**, qui permet aux filaments d'**actine** et de **myosine** de glisser les uns sur les autres. Le muscle se raccourcit. Ce glissement consomme de l'**ATP** fourni par le glucose et l'oxygène : à l'effort, le cœur et la respiration s'accélèrent."]},
  {t:"schema",k:"muscle",cap:"Du muscle à la fibre puis au sarcomère : actine et myosine glissent pour raccourcir le muscle."},
  {t:"p",ps:["Les muscles travaillent par paires opposées : quand l'**agoniste** se contracte, l'**antagoniste** se relâche. Le **biceps** fléchit le coude, le **triceps** l'étend. Même au repos, les muscles gardent une légère contraction, le **tonus**, qui maintient la posture."]},
  {t:"exemple",h:"La rhabdomyolyse",ps:["Une personne âgée retrouvée au sol après plusieurs heures : ses muscles comprimés se détruisent et libèrent leur contenu dans le sang — **myoglobine** (urines foncées « couleur Coca », risque d'**insuffisance rénale aiguë**), **potassium** (troubles du rythme) et **CPK**, enzyme dosée pour évaluer les lésions.","Rôle infirmier : bilan sanguin (CPK, kaliémie, créatinine), hydratation prescrite, surveillance de la diurèse et de la couleur des urines."]}]},
 {h:"La colonne vertébrale",chip:"Rachis",b:[
  {t:"p",ps:["La **colonne vertébrale** (rachis) soutient le tronc et la tête, protège la **moelle épinière** et permet les mouvements du dos. Elle compte **33 à 34 vertèbres** et présente des courbures qui amortissent les chocs : **lordose cervicale** (creux du cou), **cyphose thoracique** (dos arrondi), **lordose lombaire** (creux des reins).","Chaque vertèbre comprend un **corps** (en avant, porteur du poids) et un **arc** postérieur ; ensemble, ils délimitent le **canal vertébral** où passe la moelle. Entre deux vertèbres, le **disque intervertébral** (anneau fibreux entourant un noyau gélatineux) joue le rôle d'amortisseur. Entre les vertèbres sortent les **nerfs rachidiens**."]},
  {t:"table",rows:[["Cervicales","**7** (C1 = atlas, C2 = axis)","cou, très mobiles"],["Thoraciques (dorsales)","**12**","s'articulent avec les côtes"],["Lombaires","**5**","les plus grosses, portent le poids"],["Sacrum","5 vertèbres soudées","s'articule avec le bassin"],["Coccyx","3 à 5 vertèbres soudées","vestige de la queue"]].map(r=>[r[0],r[1]+" — "+r[2]])},
  {t:"exemple",h:"Repères cliniques",ps:["Chez l'adulte, la moelle épinière s'arrête vers **L1-L2** : en dessous, le canal ne contient plus que des racines nerveuses flottantes. La **ponction lombaire** se fait donc entre **L3-L4 ou L4-L5**, sans risque de piquer la moelle (repère : la ligne qui relie les deux crêtes iliaques passe par L4).","La **hernie discale** : le noyau du disque sort et comprime une racine nerveuse, le plus souvent en L4-L5 ou L5-S1 : **sciatique** (douleur irradiant dans la jambe). Des troubles urinaires ou une perte de sensibilité du périnée sont une **urgence chirurgicale** (syndrome de la queue de cheval)."]},
  {t:"retenir",txt:"Pour protéger le dos lors des manutentions : jambes fléchies, dos droit, charge près du corps, pas de torsion du tronc, et utiliser les aides techniques (lève-personne, drap de glisse)."}]},
 {h:"Le vocabulaire des mouvements",chip:"Mouvements",b:[
  {t:"p",ps:["Les mouvements se décrivent à partir de la **position anatomique de référence** : debout, face à l'observateur, bras le long du corps, paumes vers l'avant. Ce vocabulaire est utilisé dans les transmissions, en rééducation et pour décrire une déformation ou une limitation."]},
  {t:"table",rows:[["Flexion / extension","fermer / ouvrir un angle articulaire (plier le coude / le tendre)"],["Abduction / adduction","éloigner / rapprocher un membre de l'axe du corps"],["Rotation interne / externe","tourner un membre vers l'intérieur / l'extérieur autour de son axe"],["Pronation / supination","paume vers le bas / paume vers le haut (avant-bras)"],["Flexion dorsale / plantaire","relever la pointe du pied / la pointer vers le bas"],["Circumduction","mouvement circulaire combinant les précédents (épaule, hanche)"]]},
  {t:"exemple",h:"La fracture du col du fémur",ps:["Signe typique chez la personne âgée après une chute : le membre inférieur est **raccourci** et en **rotation externe** (le pied tombe vers l'extérieur), avec impossibilité de se relever. Ne pas mobiliser le membre, antalgie, prévenir le médecin."]},
  {t:"exemple",h:"La prothèse totale de hanche",ps:["Pendant les premières semaines, éviter les mouvements qui risquent de luxer la prothèse, selon la voie d'abord : le plus souvent **flexion de hanche au-delà de 90°**, **adduction** (croiser les jambes) et **rotation interne**. Fauteuil et toilettes réhaussés, coussin entre les jambes au lit."]}]},
 {h:"Vieillissement et immobilité",chip:"Immobilité",b:[
  {t:"p",ps:["Avec l'âge, la masse osseuse diminue (**ostéoporose**, surtout chez la femme après la ménopause par chute des œstrogènes), les muscles perdent masse et force (**sarcopénie**) et le cartilage s'use (**arthrose**). Le risque de **chute** et de fracture augmente : poignet, vertèbres, col du fémur.","L'**immobilité** accélère tout cela : un alitement fait perdre environ **10 à 15 % de la force musculaire par semaine** et déminéralise l'os ; les articulations s'enraidissent et des **rétractions** s'installent en quelques jours. S'y ajoutent les autres complications du décubitus : escarres, thrombose veineuse, encombrement bronchique, constipation, désorientation."]},
  {t:"cols",cols:[{h:"Prévenir",tone:"green",items:["**Lever précoce** et marche dès que possible","Mobilisation active ou passive des articulations","Positionnement correct au lit et au fauteuil","Alimentation riche en protéines, calcium, vitamine D","Activité physique adaptée, kinésithérapie"]},{h:"Repérer",tone:"amber",items:["Chutes, peur de tomber","Perte de poids, fonte musculaire","Raideurs, attitudes vicieuses (flexion des hanches et des genoux)","Douleur à la mobilisation","Dépendance qui s'installe"]}]},
  {t:"verif",items:[["Pourquoi l'ulna est-il aussi appelé cubitus ?","C'est l'ancien nom ; la terminologie internationale actuelle utilise **ulna**, comme fibula pour péroné."],["Quelles cellules fabriquent l'os ?","Les **ostéoblastes** ; les ostéoclastes le détruisent. Les deux assurent le remodelage permanent."],["Quel est le signe d'alerte majeur sous un plâtre ?","Une douleur intense, croissante, non calmée par les antalgiques (syndrome des loges), avec troubles de sensibilité ou de coloration des extrémités."],["Entre quelles vertèbres réalise-t-on une ponction lombaire ?","Entre L3-L4 ou L4-L5, sous la terminaison de la moelle (L1-L2)."],["Quelle est la position typique du membre dans une fracture du col du fémur ?","Raccourci et en rotation externe."]]},
  {t:"retenir",txt:"L'os, le muscle et l'articulation ont besoin de **mouvement** pour rester solides. Chaque journée d'alitement se paie : lever précoce, mobilisation et nutrition sont des soins à part entière."}]}
 ],
 ["206 os : soutien, protection, mouvement, réserve de calcium, moelle rouge","Os long : diaphyse (compact), épiphyses (spongieux, moelle rouge), périoste, cartilage de croissance","Ostéoblastes construisent, ostéoclastes détruisent","Consolidation : hématome, cal mou, cal osseux (6–12 semaines), remodelage","Syndrome des loges : douleur intense non calmée = urgence","Rachis : 7 cervicales, 12 thoraciques, 5 lombaires ; moelle jusqu'à L1-L2 ; PL en L4-L5","Contraction : acétylcholine, calcium, actine-myosine, ATP","Immobilité : −10 à 15 % de force par semaine ; lever précoce"]),

CV("reproduction-c","anat","Reproduction, grossesse et naissance","65 min","2.2|B.1","baby",
 ["Décrire les **appareils génitaux** masculin et féminin","Expliquer le **cycle menstruel** et ses hormones","Comprendre la **fécondation**, la nidation et le calcul du terme","Décrire le **placenta**, le développement fœtal et les modifications de la grossesse","Connaître les étapes de l'**accouchement** et du **post-partum**","Évaluer l'**adaptation du nouveau-né** et connaître la ménopause"],
 [
 {h:"L'appareil génital masculin",chip:"Masculin",b:[
  {t:"p",ps:["Les deux **testicules**, logés dans le **scrotum** hors de l'abdomen (à une température inférieure de 2 à 3 °C, nécessaire à la production des spermatozoïdes), ont une double fonction : produire les **spermatozoïdes** dans les tubes séminifères (**spermatogenèse**, environ 74 jours, continue de la puberté jusqu'à la fin de la vie) et sécréter la **testostérone**.","Les spermatozoïdes mûrissent et sont stockés dans l'**épididyme**, puis empruntent le **canal déférent** jusqu'à l'urètre. Au passage, les **vésicules séminales** et la **prostate** ajoutent le liquide qui les nourrit et les transporte : l'ensemble forme le **sperme**. L'**urètre**, qui traverse la prostate puis le **pénis**, est commun aux voies urinaires et génitales.","La **prostate**, glande de la taille d'une châtaigne située sous la vessie, entoure l'urètre : son augmentation de volume avec l'âge (**hypertrophie bénigne**) gêne l'écoulement des urines."]},
  {t:"schema",k:"homme",cap:"L'appareil génital masculin vu de profil : testicule, épididyme, canal déférent, vésicule séminale, prostate et urètre."},
  {t:"exemple",h:"Relier à la clinique",ps:["Chez l'homme âgé, l'**hypertrophie de la prostate** donne des difficultés à uriner (jet faible, levers nocturnes) et peut provoquer une **rétention aiguë d'urine** (globe vésical douloureux). Elle rend parfois le **sondage** difficile : ne jamais forcer.","La **torsion du testicule** (douleur brutale et intense d'une bourse chez l'adolescent) est une **urgence chirurgicale** : au-delà de 6 heures, le testicule risque d'être perdu.","Chez le nouveau-né, on vérifie que les testicules sont bien descendus dans les bourses (**cryptorchidie**)."]}]},
 {h:"L'appareil génital féminin",chip:"Féminin",b:[
  {t:"p",ps:["Les deux **ovaires**, dans le petit bassin, contiennent les **follicules** renfermant les ovocytes. Le stock est constitué **avant la naissance** (1 à 2 millions) et ne se renouvelle pas : seuls 400 à 500 ovocytes seront libérés au cours de la vie. Les ovaires produisent aussi les **œstrogènes** et la **progestérone**.","Les **trompes utérines** captent l'ovocyte libéré ; la **fécondation** a lieu dans leur tiers externe. L'**utérus**, muscle creux en forme de poire situé entre la vessie et le rectum, comprend un **corps** et un **col** qui s'ouvre dans le **vagin**. Sa paroi est formée d'un muscle épais, le **myomètre**, tapissé à l'intérieur par l'**endomètre**, muqueuse qui s'épaissit chaque mois et desquame lors des règles. La **vulve** forme les organes génitaux externes.","Les **seins** contiennent la **glande mammaire**, faite de lobules qui produisent le lait et de **canaux galactophores** qui l'amènent au mamelon."]},
  {t:"map",m:"femme",cap:"L'appareil génital féminin : utérus, endomètre, col, vagin, trompes, ovaires et sein"},
  {t:"exemple",h:"Relier à la clinique",ps:["La **grossesse extra-utérine** : l'œuf s'implante dans la trompe au lieu de l'utérus. Retard de règles, douleur pelvienne et saignements doivent faire penser à une GEU : risque de rupture et d'hémorragie interne, **urgence**.","Le **dépistage du cancer du col** (lié au papillomavirus, HPV) est proposé de 25 à 65 ans ; la vaccination anti-HPV est recommandée pour les filles et les garçons de 11 à 14 ans."]}]},
 {h:"Le cycle menstruel",chip:"Cycle",b:[
  {t:"p",ps:["De la puberté à la ménopause, l'organisme féminin se prépare chaque mois à une grossesse. Le cycle dure en moyenne **28 jours** (de 21 à 35 jours) ; le **premier jour des règles** est le jour 1.","Pendant la **phase folliculaire** (J1 à J14), la **FSH** fait mûrir un follicule qui sécrète des **œstrogènes** : l'endomètre s'épaissit et la glaire du col devient fluide, favorable aux spermatozoïdes. Vers **J14**, un **pic de LH** déclenche l'**ovulation** : le follicule libère l'ovocyte.","Pendant la **phase lutéale** (J14 à J28), le follicule vide devient le **corps jaune**, qui sécrète de la **progestérone** : l'endomètre se prépare à accueillir un embryon et la température corporelle monte de 0,3 à 0,5 °C. Sans fécondation, le corps jaune dégénère, les hormones chutent et l'endomètre s'élimine : ce sont les **règles**. La phase lutéale est la plus constante (14 jours) : c'est la phase folliculaire qui varie."]},
  {t:"schema",k:"menstru",cap:"Sur 28 jours : hormones hypophysaires (FSH, LH), hormones ovariennes (œstrogènes, progestérone) et évolution de l'endomètre."},
  {t:"analogie",txt:"Chaque mois, l'utérus **prépare une chambre** pour un éventuel bébé : les œstrogènes montent les murs (endomètre), la progestérone installe le mobilier. Si personne n'arrive, on vide la chambre (les règles) et on recommence."},
  {t:"exemple",h:"La pilule contraceptive",ps:["La pilule œstroprogestative apporte des hormones en continu : par **rétrocontrôle**, elle freine la FSH et la LH, ce qui **bloque l'ovulation**. Elle épaissit aussi la glaire et amincit l'endomètre. Les saignements pendant l'arrêt sont des saignements de privation, pas de vraies règles.","Un **oubli** de plus de 12 heures (pilule combinée) expose à une ovulation : conduite à tenir selon la notice, préservatif pendant 7 jours, contraception d'urgence si rapport dans les 5 jours précédents."]}]},
 {h:"Fécondation et début de grossesse",chip:"Fécondation",b:[
  {t:"p",ps:["L'ovocyte vit environ **24 heures** après l'ovulation ; les spermatozoïdes peuvent survivre **3 à 5 jours** dans les voies génitales féminines. La **fécondation**, rencontre d'un spermatozoïde et de l'ovocyte dans la trompe, forme une cellule unique à 46 chromosomes, le **zygote**. Le sexe est déterminé par le spermatozoïde (X ou Y).","L'œuf se divise en migrant vers l'utérus et s'implante dans l'endomètre vers le **7e jour** : c'est la **nidation**. Il sécrète alors l'**hCG**, hormone qui maintient le corps jaune (et donc la progestérone) et qui est détectée par les **tests de grossesse**, urinaires ou sanguins."]},
  {t:"info",txt:"En obstétrique, la grossesse se compte en **semaines d'aménorrhée (SA)**, à partir du **premier jour des dernières règles**, et non à partir de la fécondation (qui a lieu environ 2 semaines plus tard). Le terme est fixé à **41 SA** en France ; un enfant est **prématuré** avant 37 SA."},
  {t:"calc",h:"Calculer la date du terme",q:"Les dernières règles ont commencé le 1er mars. Quelle est la date présumée de l'accouchement ?",steps:["On ajoute **14 jours** au premier jour des dernières règles pour estimer la date de début de grossesse : 15 mars","On ajoute ensuite **9 mois** : 15 décembre","La date est ensuite confirmée ou corrigée par l'**échographie du 1er trimestre** (mesure de l'embryon), plus fiable"],r:"Terme présumé : **15 décembre** (41 SA)."}]},
 {h:"La grossesse",chip:"Grossesse",b:[
  {t:"p",ps:["Le **placenta**, fixé à la paroi utérine, assure les **échanges** entre la mère et le fœtus sans que leurs sangs se mélangent : oxygène et nutriments vers le fœtus, CO₂ et déchets vers la mère. Il produit des hormones (hCG, progestérone, œstrogènes). Il ne constitue **pas une barrière complète** : alcool, tabac, nombreux médicaments, certains virus et parasites le traversent.","Le **cordon ombilical** relie le fœtus au placenta ; il contient **deux artères** et **une veine** (la veine apporte le sang oxygéné au fœtus). Le fœtus baigne dans le **liquide amniotique**, qui le protège des chocs, maintient sa température et permet ses mouvements.","Jusqu'à **10 SA**, on parle d'**embryon** : c'est la période de formation des organes (**organogenèse**), la plus sensible aux agents toxiques (médicaments, alcool, infections, rayons X). Ensuite, le **fœtus** grandit et ses organes mûrissent."]},
  {t:"map",m:"grossesse",cap:"La grossesse : utérus, placenta, fœtus, cordon ombilical, liquide amniotique et col"},
  {t:"table",rows:[["Cœur et sang","volume sanguin **+40 à 50 %**, fréquence cardiaque +10 à 15/min, anémie de dilution"],["Tension artérielle","baisse au 2e trimestre ; une HTA doit faire rechercher une **prééclampsie**"],["Veine cave","comprimée par l'utérus en décubitus dorsal : malaise, hypotension → **décubitus latéral gauche**"],["Respiration","essoufflement en fin de grossesse (utérus qui remonte le diaphragme)"],["Digestif","nausées du 1er trimestre, reflux, constipation"],["Urinaire","envies fréquentes, infections urinaires favorisées"],["Métabolisme","insulinorésistance : dépistage du **diabète gestationnel**"],["Poids","prise de 9 à 15 kg selon le poids de départ"]],note:"Principales modifications de l'organisme maternel pendant la grossesse."},
  {t:"liste",items:["**7 consultations prénatales** obligatoires, à partir du 3e mois","**3 échographies** recommandées, vers **12, 22 et 32 SA**","Sérologies : toxoplasmose (mensuelle si non immunisée), rubéole, syphilis, hépatites, VIH proposé","Groupe sanguin et recherche d'agglutinines irrégulières (RAI)","Entretien prénatal précoce et préparation à la naissance"]},
  {t:"cols",cols:[{h:"Signes qui doivent faire consulter",tone:"coral",items:["Saignements","Contractions régulières avant 37 SA","Perte de liquide","Fièvre","**Maux de tête, troubles visuels, œdèmes brutaux** (prééclampsie)","Diminution des mouvements du bébé","Douleur abdominale intense"]},{h:"Prévention",tone:"green",items:["**Zéro alcool**, arrêt du tabac","Pas d'automédication ; **AINS contre-indiqués à partir de 24 SA**","Toxoplasmose : viande bien cuite, crudités lavées","Listériose : éviter fromages au lait cru, charcuterie à la coupe","Acide folique avant et en début de grossesse"]}]}]},
 {h:"L'accouchement",chip:"Accouchement",b:[
  {t:"p",ps:["L'accouchement à terme survient entre **37 et 42 SA**. Le travail est déclenché par un ensemble de signaux du fœtus et du placenta ; l'**ocytocine** et les prostaglandines provoquent des **contractions utérines** régulières, douloureuses, de plus en plus rapprochées, qui modifient le col. Le rétrocontrôle positif de l'ocytocine entretient le travail jusqu'à la naissance."]},
  {t:"etapes",items:["**Travail (dilatation)** : le col s'efface puis s'ouvre de 0 à **10 cm** ; plusieurs heures, plus long pour un premier enfant ; la poche des eaux se rompt","**Expulsion** : la tête descend dans le bassin et la mère pousse lors des contractions ; naissance","**Délivrance** : expulsion du **placenta** dans les **30 minutes** suivant la naissance ; l'utérus se rétracte pour fermer les vaisseaux"]},
  {t:"exemple",h:"L'hémorragie du post-partum",ps:["Une perte de sang de **plus de 500 mL** dans les 24 heures suivant l'accouchement définit l'hémorragie du post-partum, **première cause de mortalité maternelle**. La cause la plus fréquente est une mauvaise rétraction de l'utérus (**atonie utérine**).","Surveillance dans les 2 heures suivant l'accouchement : saignements (quantifiés), **globe utérin** (utérus dur, sous l'ombilic : bonne rétraction ; utérus mou, haut : alerte), pouls, tension, coloration. Massage utérin et appel de la sage-femme ou du médecin en cas d'anomalie."]}]},
 {h:"Le post-partum et le nouveau-né",chip:"Nouveau-né",b:[
  {t:"p",ps:["Les **suites de couches** durent environ 6 semaines. L'utérus reprend progressivement sa taille (**involution utérine**), accompagnée de contractions parfois douloureuses (« tranchées »), surtout lors des tétées. Les **lochies** (pertes de sang puis de sérosités) s'éclaircissent et diminuent en quelques semaines ; des lochies malodorantes ou de la fièvre font suspecter une infection.","Surveillance de la mère : température, pouls, tension, saignements, globe utérin, mictions, périnée ou cicatrice de césarienne, **mollets** (risque de thrombose), seins, douleur, humeur. Le **baby blues** (pleurs, irritabilité vers J3-J5) est fréquent et transitoire ; une tristesse qui dure plus de deux semaines évoque une **dépression du post-partum**, à dépister."]},
  {t:"p",ps:["À la naissance, le nouveau-né s'adapte en quelques minutes : le **premier cri** déplisse les poumons, la circulation fœtale se transforme (fermeture du **foramen ovale** entre les oreillettes et du **canal artériel**), il doit réguler sa température et, plus tard, sa glycémie. Le **score d'Apgar**, coté à 1, 5 et 10 minutes, évalue cette adaptation."]},
  {t:"table",rows:[["Fréquence cardiaque","0 : absente · 1 : < 100/min · 2 : > 100/min"],["Respiration","0 : absente · 1 : lente, irrégulière · 2 : cri vigoureux"],["Tonus","0 : flasque · 1 : faible flexion · 2 : mouvements actifs"],["Réactivité à la stimulation","0 : nulle · 1 : grimace · 2 : cri, toux"],["Coloration","0 : bleue ou pâle · 1 : corps rose, extrémités bleues · 2 : entièrement rose"]],note:"Score d'Apgar sur 10 : 7 ou plus = bonne adaptation ; en dessous, réanimation selon la gravité."},
  {t:"valeurs",rows:[["Fréquence cardiaque","au repos","120–160/min","green"],["Fréquence respiratoire","respiration abdominale","40–60/min","green"],["Température","peau à peau, bonnet","36,5–37,5 °C","green"],["Poids moyen à terme","perte physiologique jusqu'à 7–10 %, repris vers J10","≈ 3,3 kg","blue"],["Taille et périmètre crânien","à la naissance","≈ 50 cm · ≈ 35 cm","blue"]]},
  {t:"liste",items:["**Vitamine K** à la naissance (prévention des hémorragies)","**Dépistage néonatal** sur buvard à J3 (hypothyroïdie, phénylcétonurie, mucoviscidose…) et dépistage de la surdité","Ictère physiologique fréquent à partir de J2-J3 ; un ictère dans les 24 premières heures est anormal","Couchage **sur le dos**, dans un lit à lui, sans couette ni oreiller (prévention de la mort inattendue du nourrisson)"]}]},
 {h:"Allaitement, puberté et ménopause",chip:"Ménopause",b:[
  {t:"p",ps:["La **lactation** est commandée par deux hormones hypophysaires : la **prolactine** produit le lait, l'**ocytocine** l'éjecte lors de la succion. Les premiers jours, le sein produit le **colostrum**, peu abondant mais très riche en anticorps ; la **montée de lait** survient vers J2-J4. Plus le bébé tète, plus la production augmente : l'allaitement fonctionne **à la demande**.","La **puberté** (en moyenne 8 à 13 ans chez la fille, 9 à 14 ans chez le garçon) correspond à la mise en route de l'axe hypothalamus-hypophyse-gonades : développement des seins puis premières règles chez la fille, augmentation du volume des testicules, pilosité et mue de la voix chez le garçon, poussée de croissance.","La **ménopause** survient vers **51 ans** en moyenne : épuisement du stock de follicules, arrêt des règles (confirmée après **12 mois** sans règles) et chute des œstrogènes. Conséquences : bouffées de chaleur, sueurs nocturnes, sécheresse vaginale, troubles du sommeil, et à long terme **ostéoporose** et augmentation du **risque cardiovasculaire**."]},
  {t:"verif",items:[["Pourquoi les testicules sont-ils situés hors de l'abdomen ?","La production des spermatozoïdes nécessite une température inférieure de 2 à 3 °C à celle du corps."],["Quelle hormone déclenche l'ovulation ?","Le **pic de LH**, vers le 14e jour d'un cycle de 28 jours."],["Que détecte un test de grossesse ?","L'**hCG**, hormone sécrétée par l'œuf dès la nidation."],["Pourquoi installer une femme enceinte en décubitus latéral gauche ?","Pour éviter la compression de la veine cave inférieure par l'utérus, source de malaise et d'hypotension."],["Que signifie un utérus mou et haut après l'accouchement ?","Une mauvaise rétraction (atonie) : risque d'**hémorragie du post-partum**, alerte immédiate."],["Quels sont les 5 critères du score d'Apgar ?","Fréquence cardiaque, respiration, tonus, réactivité, coloration ; chacun coté de 0 à 2."]]},
  {t:"retenir",txt:"De la puberté à la ménopause, la reproduction est orchestrée par l'**hypophyse** (FSH, LH) et les **gonades**. Grossesse, accouchement et post-partum modifient profondément l'organisme : connaître les signes d'alerte (saignements, prééclampsie, hémorragie du post-partum) et l'adaptation du nouveau-né fait partie du rôle infirmier."}]}
 ],
 ["Testicules : spermatozoïdes (74 jours) et testostérone ; prostate autour de l'urètre","Ovaires : stock d'ovocytes fixé dès la naissance ; fécondation dans la trompe","Cycle de 28 jours : FSH → œstrogènes ; pic de LH à J14 → ovulation ; corps jaune → progestérone","Nidation vers J7 ; hCG = test de grossesse ; terme 41 SA ; prématurité < 37 SA","Placenta : échanges, hormones, barrière incomplète ; cordon : 2 artères, 1 veine","Grossesse : volume sanguin +40–50 % ; décubitus latéral gauche ; AINS contre-indiqués dès 24 SA","Hémorragie du post-partum > 500 mL : surveiller le globe utérin","Nouveau-né : Apgar ≥ 7 ; FC 120–160, FR 40–60 ; vitamine K, dépistage à J3"])
];
L.forEach(norm);L.forEach(c=>{const i=COURS.findIndex(x=>x.id===c.id);if(i>=0)COURS[i]=c;else COURS.push(c);});
/* ordre logique des cours d'anatomie : de la cellule aux grands appareils */
const ORD=["cellule-c","cardio-c","respi-c","sang-c","immunite-c","nerveux-c","sens-c","peau-sens-c","digestif-c","urinaire-c","equilibre-c","endocrino-c","locomoteur-c","reproduction-c"];
const idx=[];COURS.forEach((c,i)=>{if(ORD.includes(c.id))idx.push(i);});
const srt=idx.map(i=>COURS[i]).sort((a,b)=>ORD.indexOf(a.id)-ORD.indexOf(b.id));idx.forEach((i,k)=>{COURS[i]=srt[k];});})();
